// Generated by Decentraland Studio. Do not edit: this copy is kept in sync with your editor version.
// Bold white action icons for phone touch buttons and HUD hints, so a phone player sees what a button does
// instead of a generic E or F. The editor copies the PNGs into assets/images/action-icons/ when a script
// imports this module; edit or replace one there and the editor leaves it alone.
//
// actionIcon(name) is the image path: give it to declareTouchButtons from ./hudLayout,
//   declareTouchButtons([{ action: InputAction.IA_PRIMARY, icon: actionIcon('pick-up') }], { main: InputAction.IA_PRIMARY })
// or to any uiBackground texture. The names: pick-up, drop, chop, cook, wash, throw, use, serve, jump, interact,
// attack, talk.
// <ActionIcon name="chop" size={40} color={theme.text} /> draws one in UI (white, tinted by `color`).
// <ActionHint icon="chop" label="Chop" desktopKey="F" theme={theme} /> is a hint for the same action on both
// platforms: the icon and the word on a phone, the key and the word on desktop, never "F" on a phone.
import ReactEcs, { UiEntity, type UiTransformProps } from '@dcl/sdk/react-ecs'
import { isMobile } from '@dcl/sdk/platform'
import { UiText } from './uiComponents'
import type { UiColor, UiTheme } from './pure/uiTheme'

export const ACTION_ICONS = ['pick-up', 'drop', 'chop', 'cook', 'wash', 'throw', 'use', 'serve', 'jump', 'interact', 'attack', 'talk'] as const
export type ActionIconName = (typeof ACTION_ICONS)[number]
export const ACTION_ICON_DIR = 'assets/images/action-icons'

export function actionIcon(name: ActionIconName): string {
  return `${ACTION_ICON_DIR}/${name}.png`
}

export function ActionIcon(props: { name: ActionIconName; size?: number; color?: UiColor; uiTransform?: UiTransformProps }) {
  const size = props.size ?? 40
  return <UiEntity uiTransform={{ width: size, height: size, flexShrink: 0, pointerFilter: 'none', ...props.uiTransform }}
    uiBackground={{ texture: { src: actionIcon(props.name) }, textureMode: 'stretch', color: props.color }} />
}

export function ActionHint(props: { icon: ActionIconName; label: string; desktopKey?: string; theme: UiTheme; size?: number; width?: number }) {
  const size = props.size ?? 20
  const mark = Math.round(size * 1.8)
  const key = !isMobile() && props.desktopKey !== undefined
  return <UiEntity uiTransform={{ width: props.width ?? 'auto', height: mark, flexDirection: 'row', alignItems: 'center', flexShrink: 0, pointerFilter: 'none' }}>
    {key
      ? <UiEntity uiTransform={{ width: mark, height: mark, borderRadius: 6, borderWidth: 2, borderColor: props.theme.text, alignItems: 'center', justifyContent: 'center', flexShrink: 0, pointerFilter: 'none' }}>
        <UiText value={props.desktopKey ?? ''} color={props.theme.text} size={size} align="middle-center" height={mark} />
      </UiEntity>
      : <ActionIcon name={props.icon} size={mark} color={props.theme.text} />}
    <UiText value={props.label} color={props.theme.text} size={size} height={mark} uiTransform={{ width: 'auto', margin: { left: 10 } }} />
  </UiEntity>
}
